contracts/ArcPrediction.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

contract ArcPrediction is Ownable, ReentrancyGuard {
    struct Bet {
        uint256 id;
        address user;
        uint256 amount;
        uint8 direction; // 0 = DOWN, 1 = UP
        uint256 entryPrice;
        uint256 timestamp;
        uint256 duration;
        uint256 settlementPrice;
        bool settled;
        bool won;
    }

    mapping(uint256 => Bet) public bets;
    uint256 public nextBetId;
    
    // Events
    event BetPlaced(uint256 indexed id, address indexed user, uint256 amount, uint8 direction, uint256 entryPrice, uint256 duration, uint256 timestamp);
    event BetSettled(uint256 indexed id, address indexed user, uint256 settlementPrice, bool won, uint256 payout);

    constructor() Ownable(msg.sender) {}

    /**
     * @dev Place a bet using native USDC
     * @param _direction 0 for DOWN, 1 for UP
     * @param _duration duration in seconds
     * @param _entryPrice entry price with 8 decimals (Pyth standard)
     */
    function placeBet(uint8 _direction, uint256 _duration, uint256 _entryPrice) external payable nonReentrant {
        require(msg.value > 0, "Bet amount must be greater than 0");
        require(_direction == 0 || _direction == 1, "Invalid direction");

        uint256 betId = nextBetId++;
        
        bets[betId] = Bet({
            id: betId,
            user: msg.sender,
            amount: msg.value,
            direction: _direction,
            entryPrice: _entryPrice,
            timestamp: block.timestamp,
            duration: _duration,
            settlementPrice: 0,
            settled: false,
            won: false
        });

        emit BetPlaced(betId, msg.sender, msg.value, _direction, _entryPrice, _duration, block.timestamp);
    }

    /**
     * @dev Settle a bet. Only callable by owner (Keeper).
     * @param _betId ID of the bet to settle
     * @param _exitPrice Exit price with 8 decimals
     */
    function settleBet(uint256 _betId, uint256 _exitPrice) external onlyOwner nonReentrant {
        Bet storage bet = bets[_betId];
        require(!bet.settled, "Bet already settled");
        // require(block.timestamp >= bet.timestamp + bet.duration, "Bet not ready for settlement"); // Optional strict enforcement

        bet.settled = true;
        bet.settlementPrice = _exitPrice;

        bool won = false;
        if (bet.direction == 1) { // UP
            if (_exitPrice > bet.entryPrice) won = true;
        } else { // DOWN
            if (_exitPrice < bet.entryPrice) won = true;
        }

        uint256 payout = 0;
        if (won) {
            bet.won = true;
            // Calculate Multiplier based on duration (matching Solana logic)
            // 5s -> 6.9x, 10s -> 4.9x, 15s -> 1.98x
            uint256 multiplier = 198; // Default 1.98x (scaled by 100)
            if (bet.duration <= 5) multiplier = 690;
            else if (bet.duration <= 10) multiplier = 490;

            payout = (bet.amount * multiplier) / 100;
            
            // Check contract balance
            require(address(this).balance >= payout, "Insufficient contract balance for payout");
            (bool success, ) = bet.user.call{value: payout}("");
            require(success, "Payout transfer failed");
        }

        emit BetSettled(_betId, bet.user, _exitPrice, won, payout);
    }

    /**
     * @dev Deposit funds into the treasury (for payouts)
     */
    receive() external payable {}

    /**
     * @dev Withdraw funds from the contract
     */
    function withdraw(uint256 _amount) external onlyOwner {
        require(address(this).balance >= _amount, "Insufficient balance");
        (bool success, ) = msg.sender.call{value: _amount}("");
        require(success, "Withdraw failed");
    }
}

